use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn split_point(len: nat) -> (left_len: nat, right_len: nat)
    ensures
        left_len + right_len == len,
        len > 1 ==> left_len < len && right_len < len,
{
    if len == 0 {
        (0, 0)
    } else if len == 1 {
        (0, 1)  // or (1, 0) - either works
    } else {
        // For len > 1, split roughly in half
        let left = len / 2;
        let right = len - left;
        (left, right)
    }
}

fn array_split(a: Vec<i32>) -> (left: Vec<i32>, right: Vec<i32>)
    ensures
        // Sum of lengths equals original length
        left.len() + right.len() == old(a).len(),
        // Concatenation equals original
        left + right == old(a),
        // If original length > 1, both parts are strictly shorter
        old(a).len() > 1 ==> left.len() < old(a).len() && right.len() < old(a).len(),
{
    let len = a.len();
    
    if len == 0 {
        // Return two empty arrays
        (Vec::new(), Vec::new())
    } else if len == 1 {
        // For single element, put it in either array
        // Let's put it in the right array
        let mut right_vec = Vec::new();
        right_vec.push(a[0]);
        (Vec::new(), right_vec)
    } else {
        // Split at the midpoint
        let split = len / 2;
        
        // Create left part (0..split)
        let mut left_vec = Vec::new();
        let mut i = 0;
        while i < split
            invariant
                0 <= i <= split,
                left_vec.len() == i,
                forall |k: int| 0 <= k < i ==> left_vec[k] == a[k],
        {
            left_vec.push(a[i]);
            i += 1;
        }
        
        // Create right part (split..len)
        let mut right_vec = Vec::new();
        let mut j = split;
        while j < len
            invariant
                split <= j <= len,
                right_vec.len() == j - split,
                forall |k: int| split <= k < j ==> right_vec[k - split] == a[k],
        {
            right_vec.push(a[j]);
            j += 1;
        }
        
        (left_vec, right_vec)
    }
}

} // verus!

fn main() {
    // Test cases
    let empty: Vec<i32> = vec![];
    let (l1, r1) = array_split(empty);
    assert!(l1.len() == 0 && r1.len() == 0);
    
    let single = vec![42];
    let (l2, r2) = array_split(single);
    assert!(l2.len() + r2.len() == 1);
    
    let even = vec![1, 2, 3, 4];
    let (l3, r3) = array_split(even);
    assert!(l3.len() == 2 && r3.len() == 2);
    assert!(l3 + r3 == vec![1, 2, 3, 4]);
    
    let odd = vec![1, 2, 3, 4, 5];
    let (l4, r4) = array_split(odd);
    assert!(l4.len() + r4.len() == 5);
    assert!(l4 + r4 == vec![1, 2, 3, 4, 5]);
}